#include "extension_event_lifecycle.h"
#include <iostream>
using namespace moon::extension;
void check(bool b,const char* message){if(!b)throw std::runtime_error(message);}
int main(){try{
 std::vector<RuntimeEvent> trace;int full=0;EventLifecycle lifecycle({"runtime","workspace.read","commands","storage"},"en-US",[&](const auto& e){trace.push_back(e);},[&]{++full;});RuntimeRegistry registry;auto stop=registry.registerRuntime("ext",[&](const auto& e){lifecycle.event(e);});
 registry.command("ext","first","go");RuntimeEvent setting;setting.type="settings-changed";setting.payload="old";lifecycle.event(setting);registry.command("ext","second","go");setting.payload="new";lifecycle.event(setting);lifecycle.event({"clock"});lifecycle.event({"project"});lifecycle.localeChanged("ja-JP");check(trace.empty()&&lifecycle.pendingCount()==3,"Preload queue/filter");
 RuntimeEvent project;project.type="project";project.payload="snapshot";lifecycle.loaded("ext","ja-JP",project);check(trace.size()==6&&trace[0].type=="locale-changed"&&trace[0].locale=="ja-JP"&&trace[1].type=="activate"&&trace[1].extensionId=="ext"&&trace[1].apiVersion=="1.0.0"&&trace[2].payload=="snapshot"&&trace[3].commandId=="first"&&trace[4].commandId=="second"&&trace[5].payload=="new","Load ordering/payload");
 lifecycle.localeChanged("ja-JP");check(trace.size()==6,"Duplicate locale");lifecycle.localeChanged("zh-CN");check(trace.size()==7&&trace.back().locale=="zh-CN","Changed locale");lifecycle.deactivate();lifecycle.deactivate();registry.command("ext","late","go");lifecycle.loaded("ext","en-US",project);check(trace.size()==8&&trace.back().type=="deactivate"&&lifecycle.pendingCount()==0,"Deactivate idempotent/delivery blocked");stop();
 trace.clear();EventLifecycle overflow({"commands","storage"},"en-US",[&](const auto& e){trace.push_back(e);},[&]{++full;});for(int n=0;n<256;++n)overflow.event({"command",std::to_string(n)});overflow.event({"command","lost"});check(overflow.pendingCount()==256&&full==1,"Queue limit");overflow.loadFailed();overflow.event({"command","failed"});check(overflow.pendingCount()==0&&trace.empty(),"Failed load queue");
 EventLifecycle denied({},"en-US",[&](const auto& e){trace.push_back(e);});for(const auto type:{"command","settings-changed","project","window-message","files-dropped","editor-event","interaction","clock","document-saved","export-complete","locale-changed"})denied.event({type});denied.loaded("denied","en-US",project);denied.deactivate();check(trace.size()==2&&trace[0].type=="activate"&&trace[1].type=="deactivate","Permission-filtered lifecycle");
 trace.clear();EventLifecycle events({"events","windows","io"},"en-US",[&](const auto& e){trace.push_back(e);});events.loaded("events","en-US",project);for(const auto type:{"window-message","files-dropped","editor-event","interaction","clock","document-saved","export-complete"})events.event({type});check(trace.size()==8,"Authorized event families");

 int stopped=0;EventLifecycle* live=nullptr;EventLifecycle reentrant({"commands"},"en-US",[&](const auto& e){if(e.type=="deactivate"){++stopped;live->deactivate();live->event({"command","late"});throw std::runtime_error("stop callback");}if(e.type=="command")throw std::runtime_error("Late command delivered");});live=&reentrant;reentrant.loaded("reentrant","en-US",project);bool thrown=false;try{reentrant.deactivate();}catch(...){thrown=true;}reentrant.deactivate();reentrant.loaded("reentrant","en-US",project);check(thrown&&stopped==1&&reentrant.pendingCount()==0,"Throwing/reentrant deactivate finalizes lifecycle once");
 std::cout<<"Event permission, preload queue, load order, locale and teardown passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
